css:
:where(.wtyg-map-homicide_within){--bg:#0d1016;--card:rgba(17,21,30,.93);--line:#2a3142;--ink:#e9e3dc;--mute:#a9a3a8;--plum:#a0679a;--rose:#d38a9a;--bone:#efe6d8;--teal:#4aa6b5;--blue:#5d80c2}
:where(.wtyg-map-homicide_within),:where(.wtyg-map-homicide_within){margin:0;height:100%;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;background:#0d1016}
:where(.wtyg-map-homicide_within) .card{position:absolute;z-index:800;background:var(--card);border:1px solid var(--line);border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.45);backdrop-filter:blur(4px)}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="parts"],#wtyg-noid-parts){top:12px;left:12px;width:330px;max-height:calc(100% - 24px);overflow:auto;padding:12px 14px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="parts"],#wtyg-noid-parts) h1{font-size:18px;margin:0 0 2px;letter-spacing:.2px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="parts"],#wtyg-noid-parts) .lede{color:var(--mute);margin:0 0 10px;font-size:12.5px}
:where(.wtyg-map-homicide_within) .part{display:flex;gap:8px;align-items:flex-start;padding:6px 0;border-top:1px solid var(--line)}
:where(.wtyg-map-homicide_within) .part input{margin-top:3px;accent-color:#8a7fb0}
:where(.wtyg-map-homicide_within) .part label{flex:1;cursor:pointer}
:where(.wtyg-map-homicide_within) .part .n{color:var(--mute);font-size:12px}
:where(.wtyg-map-homicide_within) .sw{display:inline-block;width:11px;height:11px;border-radius:50%;margin-right:6px;vertical-align:-1px;box-shadow:0 0 8px currentColor}
:where(.wtyg-map-homicide_within) .sw.sq{border-radius:2px;box-shadow:none}
:where(.wtyg-map-homicide_within) .sub{margin:4px 0 0 0;font-size:12px;color:var(--mute)}
:where(.wtyg-map-homicide_within) .ramp{display:flex;margin-top:6px;border-radius:3px;overflow:hidden}
:where(.wtyg-map-homicide_within) .ramp span{flex:1;height:8px}
:where(.wtyg-map-homicide_within) .rampl{display:flex;justify-content:space-between;font-size:11px;color:var(--mute)}
:where(.wtyg-map-homicide_within) .keys{display:grid;grid-template-columns:1fr;gap:2px;margin-top:6px;font-size:12px}
:where(.wtyg-map-homicide_within) select{background:#151a24;color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:2px 4px;font:inherit;font-size:12px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="aboutBtn"],#wtyg-noid-aboutBtn){top:12px;right:12px;padding:7px 12px;cursor:pointer;font-weight:600}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about){top:56px;right:12px;width:420px;max-height:calc(100% - 70px);overflow:auto;padding:14px 16px;display:none}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about).open{display:block}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) h2{font-size:15px;margin:14px 0 6px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) h2:first-child{margin-top:0}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) p,:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) li{font-size:12.8px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) table{border-collapse:collapse;font-size:11.5px;width:100%}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) th,:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) td{border-bottom:1px solid var(--line);padding:2px 4px;text-align:right;white-space:nowrap}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) th:first-child,:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) td:first-child{text-align:left;white-space:normal}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) .tw{overflow:auto;max-height:340px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about) ul{padding-left:18px;margin:4px 0}
:where(.wtyg-map-homicide_within) .mute{color:var(--mute)}
:where(.wtyg-map-homicide_within) a{color:#9fc2e6}
:where(.wtyg-map-homicide_within) .leaflet-popup-content-wrapper{background:#141924;color:var(--ink);border:1px solid var(--line);border-radius:9px}
:where(.wtyg-map-homicide_within) .leaflet-popup-tip{background:#141924}
:where(.wtyg-map-homicide_within) .leaflet-popup-content{margin:12px 14px;max-height:60vh;overflow:auto;min-width:240px}
:where(.wtyg-map-homicide_within) .leaflet-container a.leaflet-popup-close-button{color:#ccc}
:where(.wtyg-map-homicide_within) .hp h3{margin:2px 0 4px;font-size:15px}
:where(.wtyg-map-homicide_within) .hp-k{font-size:10.5px;letter-spacing:.6px;text-transform:uppercase;color:#c9a3b5}
:where(.wtyg-map-homicide_within) .hp-sub{color:#a9a3a8;font-size:12px;margin:0 0 6px}
:where(.wtyg-map-homicide_within) .hp-lead{margin:4px 0 8px}
:where(.wtyg-map-homicide_within) .hp p{margin:4px 0}
:where(.wtyg-map-homicide_within) .hp-src{color:#a9a3a8;font-size:11.2px;margin-top:8px;border-top:1px solid #2a3142;padding-top:6px}
:where(.wtyg-map-homicide_within) .hp details{margin:6px 0;border:1px solid #2a3142;border-radius:6px;padding:4px 6px}
:where(.wtyg-map-homicide_within) .hp summary{cursor:pointer;font-weight:600;font-size:12.5px}
:where(.wtyg-map-homicide_within) .hp summary span{font-weight:400;color:#a9a3a8;font-size:11.5px}
:where(.wtyg-map-homicide_within) .hp .tw{overflow:auto;max-height:260px;margin-top:4px}
:where(.wtyg-map-homicide_within) .hp table{border-collapse:collapse;font-size:11px}
:where(.wtyg-map-homicide_within) .hp th,:where(.wtyg-map-homicide_within) .hp td{border-bottom:1px solid #2a3142;padding:2px 5px;text-align:right;white-space:nowrap}
:where(.wtyg-map-homicide_within) .hp td:nth-child(-n+4),:where(.wtyg-map-homicide_within) .hp th:nth-child(-n+4){text-align:left}
:where(.wtyg-map-homicide_within) .hp sup{color:#c9a3b5}
:where(.wtyg-map-homicide_within) .hp table.kv th{text-align:left;color:#a9a3a8;font-weight:500;vertical-align:top}
:where(.wtyg-map-homicide_within) .hp table.kv td{text-align:left;white-space:normal}
:where(.wtyg-map-homicide_within) .wsec{display:block}
:where(.wtyg-map-homicide_within) .wh{margin-bottom:4px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="wfilter"],#wtyg-noid-wfilter){width:100%;box-sizing:border-box;background:#151a24;color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:4px 6px;font:inherit;font-size:12.5px;margin:2px 0 6px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="wlist"],#wtyg-noid-wlist){max-height:300px;overflow:auto}
:where(.wtyg-map-homicide_within) .witem{padding:3px 0;border-top:1px solid #1f2533;font-size:12.8px}
:where(.wtyg-map-homicide_within) .witem label{cursor:pointer}
:where(.wtyg-map-homicide_within) .wlv{display:flex;flex-direction:column;gap:2px;margin:4px 0 0 18px;font-size:12px;color:var(--mute)}
:where(.wtyg-map-homicide_within) .wleg .sub{margin-left:18px}
:where(.wtyg-map-homicide_within) .hp .sub-area{margin:6px 0}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="glow"],#wtyg-noid-glow){position:absolute;inset:0;pointer-events:none;z-index:350;mix-blend-mode:screen}
:where(.wtyg-map-homicide_within) .leaflet-control-attribution{background:rgba(13,16,22,.75)!important;color:#8d8890!important}
:where(.wtyg-map-homicide_within) .leaflet-control-attribution a{color:#a7b9d0!important}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="toggleParts"],#wtyg-noid-toggleParts){display:none}
@media (max-width:720px){:where(.wtyg-map-homicide_within) :is([data-wtyg-id="parts"],#wtyg-noid-parts){width:auto;right:12px;max-height:45%;}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="parts"],#wtyg-noid-parts).min .body{display:none}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="toggleParts"],#wtyg-noid-toggleParts){display:inline-block;float:right;background:none;border:1px solid var(--line);color:var(--ink);border-radius:6px;padding:1px 8px}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="aboutBtn"],#wtyg-noid-aboutBtn){top:auto;bottom:24px;left:12px;right:auto}
:where(.wtyg-map-homicide_within) :is([data-wtyg-id="about"],#wtyg-noid-about){top:auto;bottom:66px;left:12px;right:12px;width:auto;max-height:60%}}
